{"content": """"
Pump Controller API
Endpoints for controlling 4 pumps via Arduino on COM5

POST /api/pump/<num>/set?speed=<0-255>
GET /api/pump/<num>/status
GET /api/pump/all/status
POST /api/pump/all/off
"""

import serial
from fastapi import APIRouter, HTTPException, Query
from pydantic import BaseModel
from typing import Optional

router = APIRouter(prefix="/api/pump", tags=["pump"])

PUMP_PORT = "COM5"
PUMP_BAUD = 9600
TIMEOUT = 2

def get_serial():
    return serial.Serial(PUMP_PORT, PUMP_BAUD, timeout=TIMEOUT)

class PumpResponse(BaseModel):
    pump: int
    speed: int

class AllPumpsResponse(BaseModel):
    pumps: list[int]

def send_command(cmd: str) -> str:
    """Send command to Arduino, return response"""
    try:
        with get_serial() as ser:
            ser.write((cmd + "\n").encode())
            ser.flush()
            # Wait for response
            import time
            time.sleep(0.1)
            resp = ser.read(100).decode().strip()
            return resp
    except Exception as e:
        raise HTTPException(500, f"Serial error: {e}")

@router.post("/{num}/set")
def set_pump(num: int, speed: int = Query(..., ge=0, le=255)):
    """Set pump speed (0=off, 1-255=speed)"""
    if num < 1 or num > 4:
        raise HTTPException(400, "Pump must be 1-4")

    cmd = f"P{num},{speed}"
    resp = send_command(cmd)
    return {"pump": num, "speed": speed, "response": resp}

@router.get("/{num}/status")
def get_pump_status(num: int):
    """Get pump status"""
    if num < 1 or num > 4:
        raise HTTPException(400, "Pump must be 1-4")

    cmd = f"P{num}?"
    resp = send_command(cmd)
    # Parse: P1:128
    parts = resp.split(":")
    return {"pump": int(parts[0][1]), "speed": int(parts[1])}

@router.get("/all/status")
def get_all_pumps():
    """Get all pump speeds"""
    resp = send_command("ALL?")
    # Parse: ALL:0,0,128,0
    speeds = [int(x) for x in resp.split(":")[1].split(",")]
    return {"pumps": speeds}

@router.post("/all/off")
def all_off():
    """Turn off all pumps"""
    resp = send_command("OFF")
    return {"response": resp, "all_off": True}", "path": "/home/pairaiworkstation/maati-api/pump_api.py"}

